#include "CadDocument.h"
#include "Scale.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <iostream>
#include <cmath>
#include <limits>
void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
void near(double a,double b,const char* message){check(std::abs(a-b)<1e-6,message);}
QJsonObject ref(const EvaluatedSupportFace& f){return {{"producerFeatureId",f.producerFeatureId},{"bodyId",f.bodyId},{"faceId",f.faceId}};}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument d;auto authored=d.authored();const auto id=CadDocument::newId(),bodyId=CadDocument::newId();authored["features"]=QJsonArray{QJsonObject{{"id",id},{"ownerId",authored["documentId"]},{"bodyId",bodyId},{"type","box"},{"name","ScaleFixture"},{"visible",true},{"parameters",QJsonObject{{"widthMm",20},{"depthMm",20},{"heightMm",12},{"xMm",10},{"yMm",-8},{"zMm",4}}}}};check(d.commit(authored,"Box").isEmpty(),"box");const auto before=d.bodies()[0];
 QJsonObject args{{"targetBodyId",bodyId},{"pivot","documentOrigin"},{"factor",1.5}};auto candidate=CadDocument::scaleCandidate(authored,args);const auto scaled=CadDocument::evaluateCandidate(candidate);check(scaled.ok,"scale preview");check(d.authored()==authored,"preview disposable");
 auto verify=[&](const EvaluatedBody& b,double factor){check(b.bodyId==bodyId && b.featureId==id,"identity");near(b.summary["volumeMm3"].toDouble(),4800*factor*factor*factor,"factor cubed volume");check(b.supportFaces.size()==before.supportFaces.size() && b.solidEdges.size()==before.solidEdges.size(),"reference counts");for(size_t i=0;i<b.supportFaces.size();++i){auto a=b.supportFaces[i],old=before.supportFaces[i];check(ref(a)==ref(old),"face identity");for(const auto* key:{"normal","uAxis","vAxis"})check(a.frame[key]==old.frame[key],"normalized axes unchanged");for(int j=0;j<3;++j)near(a.frame["origin"].toArray()[j].toDouble(),factor*old.frame["origin"].toArray()[j].toDouble(),"frame origin");for(size_t j=0;j<a.boundaryEdges.size();++j)check(a.boundaryEdges[j].edgeId==old.boundaryEdges[j].edgeId,"boundary identity");}for(size_t i=0;i<b.solidEdges.size();++i){check(b.solidEdges[i].edgeId==before.solidEdges[i].edgeId,"edge identity");for(const auto* key:{"startMm","endMm","centerMm"})if(before.solidEdges[i].provenance.contains(key))for(int j=0;j<3;++j)near(b.solidEdges[i].provenance[key].toArray()[j].toDouble(),factor*before.solidEdges[i].provenance[key].toArray()[j].toDouble(),"scaled provenance");}};
 verify(scaled.evaluation->bodies[0],1.5);check(d.commit(candidate,"Scale").isEmpty(),"commit");args["featureId"]=candidate["features"].toArray().last().toObject()["id"];args["factor"]=2;candidate=CadDocument::scaleCandidate(d.authored(),args);check(d.commit(candidate,"Edit Scale").isEmpty(),"edit");verify(d.bodies()[0],2);d.history().undo();verify(d.bodies()[0],1.5);d.history().redo();verify(d.bodies()[0],2);
 const auto good=d.authored();for(const double bad:{0.,-1.,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){args["factor"]=bad;bool rejected=false;try{rejected=!d.commit(CadDocument::scaleCandidate(good,args),"invalid").isEmpty();}catch(...){rejected=true;}check(rejected && d.authored()==good,"invalid factor atomic");}
 args["factor"]=1;args["pivot"]="centroid";bool rejected=false;try{CadDocument::scaleCandidate(good,args);}catch(...){rejected=true;}check(rejected,"non-origin pivot refused");args["pivot"]="documentOrigin";args["targetBodyId"]=CadDocument::newId();check(!d.commit(CadDocument::scaleCandidate(good,args),"stale").isEmpty() && d.authored()==good,"missing target atomic");
 auto nonroot=good;nonroot["objectOwners"]=QJsonObject{{"bodies",QJsonObject{{bodyId,CadDocument::newId()}}}};bool rootRejected=false;try{Scale::evaluate(*scaled.evaluation,good["features"].toArray().last().toObject(),nonroot);}catch(const GeometryKernel::EvaluationError& e){rootRejected=e.diagnostics().value("code")=="scale_root_required";}check(rootRejected,"nonroot explicitly refused");
 auto occurrence=*scaled.evaluation;occurrence.bodies[0].occurrenceId=CadDocument::newId();bool occurrenceRejected=false;try{Scale::evaluate(occurrence,good["features"].toArray().last().toObject(),good);}catch(const GeometryKernel::EvaluationError&){occurrenceRejected=true;}check(occurrenceRejected,"occurrence refused");
 QTemporaryDir temp;auto path=temp.filePath("scale.alloy");check(d.save(path).isEmpty(),"save");CadDocument reopened;check(reopened.open(path).isEmpty() && reopened.authored()==good,"reopen");verify(reopened.bodies()[0],2);
 std::cout<<"Scale exact copied topology/identity/normalized frames/provenance, factor-cubed volume, edit/history/reopen and atomic refusals passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
